import time
import Lattice as lat
import numpy as np
from auxiliary import quicksort

class Hr:
    def __init__(self):
        self.supercell_lat=np.eye(3)
        pass
    # read hopping matrix generated by WANNIER90 v2.X
    def readSingleFile(self,filepath,ignoreImagPart=True,cutoff=-1,format="VASP"):
        time0=time.time()
        with open(filepath,'r') as fin:
            data=fin.read().split('\n')
            print('reading file %s, title line:%s'%(filepath,data[0]))
            self.norb=int(data[1])
            if format=="QE": assert self.norb%2==0, "format is set to QE, means we are doing soc case, but norb is odd"
            self.onsite=[0.]*self.norb

            totWaveVectors=int(data[2])
            iline=3
            recordedWaveVectors=0
            while(True):
                waveVectorPack=data[iline].split()
                recordedWaveVectors+=len(waveVectorPack)
                iline+=1
                if recordedWaveVectors>=totWaveVectors:break
            
            self.bondList=[]
            nTotal,nSkip=0,0
            while(True):
                lineinfo=data[iline].split()
                if len(lineinfo)==7:
                    R1, R2, R3, sourceID, targetID, t_real, t_imag = int(lineinfo[0]),int(lineinfo[1]),int(lineinfo[2]),int(lineinfo[3])-1,int(lineinfo[4])-1,float(lineinfo[5]),float(lineinfo[6])
                    t=t_real if ignoreImagPart else t_real + 1j*t_imag
                    if format=="QE":
                        sourceID=(sourceID%2)*(self.norb//2)+sourceID//2
                        targetID=(targetID%2)*(self.norb//2)+targetID//2
                    nTotal+=1
                    if abs(t)>cutoff:
                        self.bondList.append(lat.BondDigital(sourceID,targetID,[R1,R2,R3],t))
                        if R1==0 and R2 ==0 and R3==0 and sourceID==targetID:
                            self.onsite[sourceID]=t_real
                            assert t_imag<1e-4, 'found complex onsite energy on orb%d'%sourceID
                    else:
                        nSkip+=1
                iline+=1
                if iline>=len(data):break
            #print(self.bondList)
            #exit()
            print('file %s has been successfully read in %.3fms, %d/%d skipped'%(filepath,1000*(time.time()-time0),nSkip,nTotal))

    def readSingleTBFile(self,filepath,ignoreImagPart=False,format="VASP"):
        time0=time.time()
        with open(filepath,'r') as fin:
            data=[line for line in fin.read().split('\n') if line!='' and line!=' ']
            print('reading file %s, title line:%s'%(filepath,data[0]))
            self.norb=int(data[4])
            if format=="QE": assert self.norb%2==0, "format is set to QE, means we are doing soc case, but norb is odd"
            self.onsite=[0.]*self.norb

            totWaveVectors=int(data[5])
            iline=6
            recordedWaveVectors=0
            #print(totWaveVectors)
            while(True):
                waveVectorPack=[int(x) for x in data[iline].split(' ') if x!='']
                #for x in waveVectorPack:
                #    recordedWaveVectors+=x
                recordedWaveVectors+=len(waveVectorPack)#sum(waveVectorPack)
                iline+=1
                #print(waveVectorPack,recordedWaveVectors)
                if recordedWaveVectors>=totWaveVectors:break
            
            firstRvec=[]
            self.bondList=[]
            self.rvecList=[]
            while(True):
                lineinfo=data[iline].split()
                if len(lineinfo)==3:
                    Rvec=np.array([int(x) for x in lineinfo])
                    if len(firstRvec)==0: 
                        firstRvec=np.array(list(Rvec))
                    else:
                        if (Rvec==firstRvec).all():
                            print("hopping matrix has been read.")
                            break
                if len(lineinfo)==4:
                    R1, R2, R3=Rvec
                    sourceID, targetID, t_real, t_imag = int(lineinfo[0])-1,int(lineinfo[1])-1,float(lineinfo[2]),float(lineinfo[3])
                    t=t_real if ignoreImagPart else t_real + 1j*t_imag
                    if format=="QE":
                        sourceID=(sourceID%2)*(self.norb//2)+sourceID//2
                        targetID=(targetID%2)*(self.norb//2)+targetID//2
                    self.bondList.append(lat.BondDigital(sourceID,targetID,Rvec,t))
                    if R1==0 and R2 ==0 and R3==0 and sourceID==targetID:
                        self.onsite[sourceID]=t_real
                        assert t_imag<1e-4, 'found complex onsite energy on orb%d'%sourceID
                iline+=1
                if iline>=len(data):break
            
            #rmnList[sourceID][targetID][rx,ry,rz][rVec]
            self._rmnList=[[[[] for k in range(3)] for j in range(self.norb)] for i in range(self.norb)]
            while(True):
                lineinfo=data[iline].split()
                if len(lineinfo)==3:
                    Rvec=np.array([int(x) for x in lineinfo])
                    self.rvecList.append(Rvec)
                if len(lineinfo)==8:
                    sourceID, targetID, rx_real, rx_imag, ry_real, ry_imag, rz_real, rz_imag = [float(x) for x in lineinfo]
                    sourceID, targetID=int(sourceID)-1, int(targetID)-1
                    self._rmnList[sourceID][targetID][0].append(rx_real+1j*rx_imag)
                    self._rmnList[sourceID][targetID][1].append(ry_real+1j*ry_imag)
                    self._rmnList[sourceID][targetID][2].append(rz_real+1j*rz_imag)
                iline+=1
                if iline>=len(data):break
            self.rmnList=np.array(self._rmnList)
            #print(self.bondList)
            #exit()

            print('file %s has been successfully read in %.3fms'%(filepath,1000*(time.time()-time0)))

    # read up- and dn-spin hopping matrix generated by WANNIER90 v2.X
    def readDoubleFiles(self,filepath1,filepath2,ignoreImagPart=True,cutoff=-1):
        time0=time.time()
        with open(filepath1,'r') as fin:
            data=fin.read().split('\n')
            print('reading file %s, title line:%s'%(filepath1,data[0]))
            self.norb=int(data[1])*2
            self.onsite=[0.]*self.norb

            totWaveVectors=int(data[2])
            iline=3
            recordedWaveVectors=0
            while(True):
                waveVectorPack=data[iline].split()
                recordedWaveVectors+=len(waveVectorPack)
                iline+=1
                if recordedWaveVectors>=totWaveVectors:break
            
            self.bondList=[]
            nTotal,nSkip=0,0
            while(True):
                lineinfo=data[iline].split()
                if len(lineinfo)==7:
                    R1, R2, R3, sourceID, targetID, t_real, t_imag = int(lineinfo[0]),int(lineinfo[1]),int(lineinfo[2]),int(lineinfo[3])-1,int(lineinfo[4])-1,float(lineinfo[5]),float(lineinfo[6])
                    t=t_real if ignoreImagPart else t_real + 1j*t_imag
                    nTotal+=1
                    if abs(t)>cutoff:
                        self.bondList.append(lat.BondDigital(sourceID,targetID,[R1,R2,R3],t))
                        if R1==0 and R2 ==0 and R3==0 and sourceID==targetID:
                            self.onsite[sourceID]=t_real
                            assert t_imag<1e-4, 'found complex onsite energy on orb%d'%sourceID
                    else:
                        nSkip+=1
                iline+=1
                if iline>=len(data):break
            #print(self.bondList)
            #exit()
            print('file %s (spin-up) has been successfully read in %.3fms, %d/%d skipped'%(filepath1,1000*(time.time()-time0),nSkip,nTotal))

        with open(filepath2,'r') as fin:
            data=fin.read().split('\n')
            print('reading file %s, title line:%s'%(filepath2,data[0]))
            assert self.norb==int(data[1])*2, 'The two Hr files were assumed to have the same number of orbs'
            #self.onsite_dn=[0.]*self.norb

            totWaveVectors=int(data[2])
            iline=3
            recordedWaveVectors=0
            while(True):
                waveVectorPack=data[iline].split()
                recordedWaveVectors+=len(waveVectorPack)
                iline+=1
                if recordedWaveVectors>=totWaveVectors:break
            
            #self.bondList=[]
            while(True):
                lineinfo=data[iline].split()
                if len(lineinfo)==7:
                    R1, R2, R3, sourceID, targetID, t_real, t_imag = int(lineinfo[0]),int(lineinfo[1]),int(lineinfo[2]),int(lineinfo[3])-1,int(lineinfo[4])-1,float(lineinfo[5]),float(lineinfo[6])
                    t=t_real if ignoreImagPart else t_real + 1j*t_imag
                    if abs(t)>cutoff:
                        self.bondList.append(lat.BondDigital(sourceID+self.norb//2,targetID+self.norb//2,[R1,R2,R3],t))
                        if R1==0 and R2 ==0 and R3==0 and sourceID==targetID:
                            self.onsite[sourceID+self.norb//2]=t_real
                            assert t_imag<1e-4, 'found complex onsite energy on orb%d'%sourceID
                iline+=1
                if iline>=len(data):break
            print('file %s (spin-dn) has been successfully read in %.3fms'%(filepath1,1000*(time.time()-time0)))

    # transform Hr data of cell into Hr of supercell
    def make_supercell(self,sc_dir0=[1.,1.,0.],sc_dir1=[1.,-1.,0.],sc_dir2=[0.,0.,1.],soc=False):#,toHome=True):
        '''
        construct a supercell model.
        often used with slab fun. to get slab model with chosen border.
        '''
        Tmatrix=np.array([sc_dir0,sc_dir1,sc_dir2])  # sc_lat = T dot lat 
        invTmatrix=np.linalg.inv(Tmatrix)            #    lat = invT dot sc_lat
        # construct lattice matrix for supercell
        self.supercell_lat=Tmatrix#np.dot(Tmatrix,self.lattice) # just treat original cell as simple cubic
    
        # construct orbitals for supercell
        R0max=int(np.max(abs(Tmatrix[:,0])))
        R1max=int(np.max(abs(Tmatrix[:,1])))
        R2max=int(np.max(abs(Tmatrix[:,2])))
        Rmax=np.max([R0max,R1max,R2max])
        
        ### find which sub-cell is interior, just check the origins
        interior_cell_list=[] # store Bravais lattice vectors in original cell coordinates
        #interior_cell_coor=[] # store Bravais lattice vectors in supercell coordinates
        for a0 in range(-Rmax,Rmax+1):
            for a1 in range(-Rmax,Rmax+1):
                for a2 in range(-Rmax,Rmax+1):
                    ori_lat=np.array([a0,a1,a2])
                    ori_sc_lat=np.dot(ori_lat,invTmatrix)
                    interior=True
                    for ori_coor in ori_sc_lat:
                        if(ori_coor<0 or ori_coor>=1):
                            interior=False
                    if(interior):
                        #print(ori_lat)
                        interior_cell_list.append(ori_lat)
                        #interior_cell_coor.append(ori_sc_lat)
        #print("%d cells included in supercell"%len(interior_cell_list))
        #exit()
        ### now add every orbs and their attributes
        #sc_orbital_coor=[]
        norbital=self.norb*len(interior_cell_list)
        onsite_energy=np.zeros(norbital)
        
        hopping=[]
        nhoppings=0
        for iinter_cell, interior_cell in enumerate(interior_cell_list):
            for iorb0 in range(self.norb):
                # add coordinates; no need to know exact coordinates of orbitals
                #orb_sc=np.dot(orb0+interior_cell,invTmatrix)
                #sc_orbital_coor.append(orb_sc)
                #norbital+=1
                orb0_index_sc=iinter_cell*self.norb+iorb0
                if soc:
                    half_index=iorb0%(self.norb//2)
                    if iorb0<self.norb//2:
                        orb0_index_sc=iinter_cell*(self.norb//2)+half_index
                    else:
                        orb0_index_sc=iinter_cell*(self.norb//2)+half_index+norbital//2
                # add on-site energy
                onsite_energy[orb0_index_sc]=self.onsite[iorb0]#.append(self.onsite[iorb0])
                # add hopping
                #print("--> source orb%d, id in supercell %d"%(iorb0,orb0_index_sc))
                for bond in self.bondList:
                    if(bond.source==iorb0):
                        #iorb0_sc=iinter_cell*self.norb+iorb0
                        #hopping_orb0=[iorb0_sc]
                        iorb1, aug_vec = bond.target, bond.overlat
                        #print('iorb0, iorb1:', iorb0, iorb1, 'aug_vec:',aug_vec)
                        orb1_cell_ori=interior_cell+aug_vec # the origin coordinates (a1,a2,a3 lattice)
                        orb1_cell_ori_sc=np.dot(orb1_cell_ori,invTmatrix) # in supercell lattice
                        orb1_cell_ori_sc_reduced=orb1_cell_ori_sc%1       # reduced by 1
                        aug_vec_sc=np.array([int(x) for x in (orb1_cell_ori_sc-orb1_cell_ori_sc_reduced)]) # aug vector in supercell frame
                        
                        orb1_coor_reduced=orb1_cell_ori-np.dot(aug_vec_sc,Tmatrix)
                        #print("bond to orb%d, overLat: %d %d %d, ori: %d %d %d, sc: %.3f %.3f %.3f, sc reduced: %d %d %d, aug: %d %d %d, t:(%.1f, %.1f)"%(
                        #    bond.target,*bond.overlat,*orb1_cell_ori,*orb1_cell_ori_sc_reduced,*orb1_coor_reduced,*aug_vec_sc,bond.t.real,bond.t.imag))
                        #print("target in origianl %d %d %d, sc %.3f %.3f %.3f"%(*orb1_cell_ori,*orb1_cell_ori_sc_reduced))
                        
                        #orb1_cell_ori_sc_reduced=np.array([int(x) for x in np.dot(orb1_cell_ori_sc_reduced,Tmatrix)])
                        # check which level is reached
                        for iori_coor, ori_coor in enumerate(interior_cell_list):
                            if(ori_coor==orb1_coor_reduced).all():
                                orb1_index_sc=iori_coor*self.norb+iorb1
                                if soc:
                                    half_index=iorb1%(self.norb//2)
                                    if iorb1<self.norb//2:
                                        orb1_index_sc=iori_coor*(self.norb//2)+half_index
                                    else:
                                        orb1_index_sc=iori_coor*(self.norb//2)+half_index+norbital//2
                                #print("in sc coor. bond to orb%d, overLat: %d %d %d"%(orb1_index_sc,*aug_vec_sc))
                                break
                        #print('SC: iorb0, iorb1:', iorb0_sc, iorb1_sc, 'aug_vec:',aug_vec_sc)
                        hopping_orb0=lat.BondDigital(orb0_index_sc,orb1_index_sc,aug_vec_sc,bond.t)#[iorb0_sc, iorb1_sc, aug_vec_sc, amplify]
                        hopping.append(hopping_orb0)
                        nhoppings+=1
        #exit()
        self.norb=norbital
        self.onsite=onsite_energy
        self.bondList=hopping
    
    def sortOverlap(self,idirection=0):
        # try to adjust coordinates of orbs, to reduce the number in overlat
        direction_list=[[0,0,0],[0,0,0]] # direction_list[idirection][ioverlat][trial_enhancement]
        direction_list[0][idirection]=1
        direction_list[1][idirection]=-1
        direction_vec=np.array(direction_list)
        changed=True
        cnt=0
        while(changed and cnt<self.norb*self.norb): # greedy algo.
            cnt+=1
            #print("trial %d"%cnt)
            changed=False
            for iorb in range(self.norb):
                shift_list=[np.zeros(3,dtype=int),direction_vec[0],direction_vec[1]]
                summed_overlat=[]
                #print('orb%d'%iorb)
                for shift in shift_list:
                    overlat=0
                    for bond in self.bondList:
                        if bond.source==bond.target: continue
                        if bond.source==iorb:
                            overlat+=abs(bond.overlat+shift)
                        if bond.target==iorb:
                            overlat+=abs(bond.overlat-shift)
                    #print("shift %d %d %d overlat %d %d %d"%(*shift,*overlat))
                    summed_overlat.append(sum(overlat))
                    
                #print('summed overlat in three proposals: %d %d %d'%(*summed_overlat,))
                orderIndex=quicksort(summed_overlat)
                #print('sorted index: %d %d %d'%(*orderIndex,))
                optimal_shift=shift_list[orderIndex[0]] if summed_overlat[0]<summed_overlat[1] else np.zeros(3,dtype=int)
                
                #print(iorb,optimal_shift)
                if (optimal_shift!=0).any():
                    changed=True
                    print('change position of orb%d by (%d %d %d)'%(iorb,*optimal_shift))
                    for bond in self.bondList:
                        if bond.source==bond.target: continue
                        if bond.source==iorb:
                            bond.overlat+=optimal_shift
                        elif  bond.target==iorb:
                            bond.overlat-=optimal_shift
        print("sorted in %d loops"%cnt)

    def cutSharpEdge(self,cutDir=1,orb_shift=0.5):
        '''drop over border hopping to make a slab model'''
        'return the num. of broken bonds, adjust orb_shift to make this as low as possible'
        # adjust the position of each orb
        shift_vec=np.zeros(3)
        shift_vec[cutDir]+=orb_shift
        #for orb in self.orbital_coor:
        #    orb+=shift_vec
        #self.toHome()
        
        # cutoff the hopping
        hopping_update=[]
        nhoppings=0
        ndropping=0
        for bond in self.bondList:
            if(abs(bond.overlat[cutDir])<1e-5):
                hopping_update.append(bond)
                nhoppings+=1
            else:
                ndropping+=1
                
        self.bondList=hopping_update
        #self.nhoppings=nhoppings
        print('dropping bonds:',ndropping)
        return ndropping